"""Cadre HMI base: session-wide helpers. Generated by Cadre HMI Library tools/hmi."""

PALETTE_THEME = {"day": "light-cool", "bright": "light-cool", "dusk": "dark-cool", "night": "dark-cool"}
PRIORITIES = ["Critical", "High", "Medium", "Low", "Diagnostic"]
ACTIVE = ["ActiveUnacked", "ActiveAcked"]
UNACKED = ["ActiveUnacked", "ClearUnacked"]


def set_palette(session, palette):
	"""The brilliance menu: one palette for the whole session, the Ignition theme in step."""
	session.custom.palette = palette
	session.props.theme = PALETTE_THEME.get(palette, "light-cool")


FACEPLATE_STYLES = ["openbridge", "asm"]


def faceplate_style(session, device_id):
	"""The faceplate style of a device (COBD-045): its device model's (`faceplate` of its index entry),
	else the project's default (`session.custom.faceplateStyle`), else `openbridge`."""
	try:
		s = _device_entry(session, device_id)["faceplate"]
	except Exception:
		s = None
	if s not in FACEPLATE_STYLES:
		try:
			s = session.custom.faceplateStyle
		except Exception:
			s = None
	if s in FACEPLATE_STYLES:
		return s
	return "openbridge"


def select_device(session, device_id, kind, title="", label="", tab="", local=None):
	"""The faceplate dock contract: written together before the dock opens. The title is the
	device identifier shown on the symbol (its ID tag), else the last segment of the folder. The
	style comes first, so that the dock never draws the new device in the old device's style. The tab
	is the key of the faceplate tab to open on (`home`, `config`, `alarms`, ...), written last: the
	faceplate shows it when it is one of its shown tabs, else its first. A plain symbol click names
	none, so it clears the tab a call before it asked for and opens the first. `local` is the kind of a local
	assembly (the `<Kind>` of its views `Local/<Kind>/Assembly` and `Local/<Kind>/Home`): the local faceplate reads it as `localKind` to embed the
	kind's Home, and every other call clears it (NOTE-WFB-10 section 11.2 item 5)."""
	session.custom.selectedStyle = faceplate_style(session, device_id)
	session.custom.selectedLocal = local or ""
	session.custom.selectedDevice = device_id
	session.custom.selectedKind = kind
	session.custom.selectedTitle = title or device_id.split("/")[-1]
	session.custom.selectedLabel = label
	try:
		session.custom.selectedTab = tab if tab and tab_shown(session, device_id, tab) else ""
	except Exception:
		session.custom.selectedTab = ""


# Service data also fills the Config tab of a generator (COB-158): the hours since the last service and the
# Service completed command, beside the configuration rows and the maintenance functions.
CONFIG_SERVICE = ["serviceHours", "cmdServiceDone"]


def tab_shown(session, device_id, tab):
	"""Whether the faceplate of a device shows the tab asked for (COB-158 contract 2.1), for the tabs a device may
	lack: Interlock (the device has an `ilk` folder), and Config or Maintenance (a maintenance row, a
	configuration row or, for Config, service data). Every other tab is always shown; a key the faceplate does not
	have is refused by the view, which opens its first tab."""
	d = (device_id or "").strip()
	if tab == "interlocks":
		return bool(interlock_summary(d, session)["present"])
	if tab in ("config", "maintenance"):
		if len(_entry_config(_device_entry(session, d))) > 0:   # its configuration rows, which no member read counts
			return True
		rows = MNT_FORCE_PAIR + MNT_FORCE_MODE + [MNT_MASK] + [m for m, _text in MNT_FLAGS]
		extra = CONFIG_SERVICE if tab == "config" else []
		read = device_read(session, d, rows + extra)
		return bool(read["mnt"]) or read["config"] > 0 or len([m for m in extra if read["has"].get(_key(m))]) > 0
	return True


def page_title(session, path):
	"""The navigation menu label of the current route, else the route itself."""
	try:
		for group in ("items", "footer"):
			for item in session.custom.nav[group]:
				if item["path"] == path:
					return item["label"]
	except Exception:
		pass
	return path


def _accessor(event, name, default=""):
	try:
		return getattr(event, name)()
	except Exception:
		return default


def alarm_summary(scope="*"):
	"""Counts, the highest active priority, and the most severe active alarm's text and time,
	for the alarms whose source path matches `scope` (the project's `session.custom.alarmScope`;
	`queryStatus` documents the `*` wildcard on `path`)."""
	out = {"count": 0, "unacked": 0, "highest": "", "topLabel": "", "topTime": "", "topId": "", "topSource": ""}
	paths = [scope or "*"]
	try:
		out["count"] = len(system.alarm.queryStatus(path=paths, state=ACTIVE))
		out["unacked"] = len(system.alarm.queryStatus(path=paths, state=UNACKED))
		for p in PRIORITIES:
			events = system.alarm.queryStatus(path=paths, state=ACTIVE, priority=[p])
			if len(events) > 0:
				top = events[0]
				out["highest"] = p
				out["topId"] = unicode(_accessor(top, "getId"))
				out["topSource"] = unicode(_accessor(top, "getSource"))
				out["topLabel"] = unicode(_accessor(top, "getLabel") or _accessor(top, "getDisplayPath") or _accessor(top, "getSource"))
				data = _accessor(top, "getActiveData", None)
				if data is not None:
					ts = data.getTimestamp()
					try:
						out["topTime"] = system.date.format(system.date.fromMillis(long(ts)), "HH:mm:ss")
					except Exception:
						out["topTime"] = system.date.format(ts, "HH:mm:ss")
				break
	except Exception as e:
		out["error"] = unicode(e)
	return out


# Command security (COB-063, NOTE-COB-04, COBD-024): every write path requires the gateway's admin role.
# The role's name is read from the gateway, not assumed: experiment E5 found one role, "Administrator", in
# the user source "default" behind the identity provider "default" (wiki page 07, GF-43). The session's
# roles come from `session.props.auth.user.roles`, null while nobody is signed in (GF-43).
ADMIN_ROLE = "Administrator"
WRITE_PATHS = ["W1", "W2", "W3", "W4", "W5", "W6", "W7", "W8", "W9", "W10", "W11", "W12", "W13", "W14", "W15",
	"W16", "W17", "W18", "W19"]
PERMITTED = dict((w, [ADMIN_ROLE]) for w in WRITE_PATHS)
REFUSED = "Refused: sign in with the Administrator role"


def roles(session):
	"""The roles of the session's signed in user; empty while nobody is signed in."""
	try:
		a = session.props.auth
		if not a.authenticated:
			return []
		return [unicode(r) for r in (a.user.roles or [])]
	except Exception:
		return []


def allowed(session, path):
	"""The session's user holds a role that write path `path` permits."""
	permitted = PERMITTED.get(path, [])
	return len([r for r in roles(session) if r in permitted]) > 0


def permissions(session):
	"""`custom.can` of a view: each write path's permission, for the advisory `enabled` bindings. The
	check in each write function is the control (NOTE-COB-04 section 6.2 step 5)."""
	return dict((w, allowed(session, w)) for w in WRITE_PATHS)


def session_user(session=None):
	"""The acknowledging user: the signed in user's name, else None. Acknowledgement is refused
	before it is asked for while nobody is signed in, so no event carries a made up name."""
	try:
		if session is not None and session.props.auth.authenticated:
			return session.props.auth.user.userName
	except Exception:
		pass
	return None


def ack_top(scope="*", session=None):
	"""Acknowledge the most severe active alarm in scope (the top bar ACK button, write path W6).
	Perspective scripts run in gateway scope, where `acknowledge` takes a third, required argument,
	the user (IGW:22 section 3.1, the gateway overload); without it nothing is acknowledged (GF-21)."""
	if not allowed(session, "W6"):
		return REFUSED
	s = alarm_summary(scope)
	if not s.get("topId"):
		return []
	failed = system.alarm.acknowledge([s["topId"]], "Acknowledged from the top bar", session_user(session))
	if s["topId"] not in [unicode(i) for i in (failed or [])]:
		_relay_ack(session, "W6", [tag_id(s.get("topSource"), _devices_of(session))])
	return failed


# A device's alarms (COB-076): every alarm whose source lies under the device folder. The source
# format and the pattern were measured by experiment E4 on the 8.3.6 gateway (wiki page 07, GF-34).
LIST_STATES = ["ActiveUnacked", "ActiveAcked", "ClearUnacked"]   # the stock table's default states
NO_MATCH = "prov:none:/tag:none/none"


def device_source(device_id):
	"""The source path pattern of every alarm under a device folder: '[default]cadre_hmi_wtp/P502'
	gives 'prov:default:/tag:cadre_hmi_wtp/P502/*'. The source format is measured (GF-34); the
	trailing slash keeps P501's alarms out of a P50 list. A folder without a provider matches
	nothing, never everything."""
	d = (device_id or "").strip()
	if not d.startswith("[") or "]" not in d:
		return NO_MATCH
	prov, path = d[1:].split("]", 1)
	path = path.strip("/")
	if not prov or not path:
		return NO_MATCH
	return "prov:%s:/tag:%s/*" % (prov, path)


def _device_entry(session, device_id):
	"""The device's entry in the generator's device index (`session.custom.devices`), else None."""
	d = (device_id or "").strip()
	try:
		for x in session.custom.devices:
			if x["folder"] == d:
				return x
	except Exception:
		pass
	return None


def _entry_list(entry, key):
	"""A list a device model adds to a device's index entry (`sources`, `write`, `members`), as text;
	None where the entry has none, which is every device of a project built without a device model."""
	try:
		v = entry[key]
	except Exception:
		return None
	if v is None:
		return None
	return [unicode(i) for i in v]


def device_sources(session, device_id):
	"""The source path patterns of a device's alarms. A device model may leave a device's alarms on
	source tags outside its folder and name them (`sources` of the device index, for example
	'prov:default:/tag:site/P1_OE:/alm:*'); a device without the list has the one folder pattern of
	`device_source`. A list given empty matches nothing: the device has no alarm."""
	if unicode(device_id or "").startswith("tag:"):   # a fault row of a page: the alarms on one tag (COB-159)
		return [tag_source(unicode(device_id)[4:])]
	src = _entry_list(_device_entry(session, device_id), "sources")
	if src is None:
		return [device_source(device_id)]
	return [s for s in src if s] or [NO_MATCH]


def _paths(scope, source):
	"""The `path` list of an alarm query: a device's source patterns, else the project scope.
	`queryStatus` takes several patterns as a list and answers nothing for two patterns in one comma
	separated string (measured, GF-52), so the comma separated form the stock table takes is split."""
	if not source:
		return [scope or "*"]
	if hasattr(source, "split"):
		return [s for s in source.split(",") if s] or [scope or "*"]
	return [unicode(s) for s in source if s] or [scope or "*"]


def alarm_count(scope="*", source=""):
	"""The number of alarms the list shows (its states, every priority); `source` is one pattern or
	several, as `_paths` takes them."""
	try:
		return len(system.alarm.queryStatus(path=_paths(scope, source), state=LIST_STATES))
	except Exception:
		return 0


# The alarm list (COB-077): alarm events as package Alert records. Every accessor below was
# measured by experiment E4 before use (wiki page 07, GF-35 and GF-36).
ALERT_TYPE = {"Critical": "level-critical", "High": "level-high", "Medium": "level-medium",
	"Low": "level-low", "Diagnostic": "level-diagnostic"}
TYPE_RANK = ["level-critical", "level-high", "level-medium", "level-low", "level-diagnostic"]


def _matches(pattern, text):
	"""`text` matches a source pattern, in which `*` stands for any run of characters."""
	parts = unicode(pattern or "").split("*")
	if len(parts) == 1:
		return parts[0] == text
	if not text.startswith(parts[0]) or not text[len(parts[0]):].endswith(parts[-1]):
		return False
	at = len(parts[0])
	for part in parts[1:-1]:
		at = text.find(part, at)
		if at < 0:
			return False
		at += len(part)
	return at <= len(text) - len(parts[-1])


# A device symbol's alarm state (F016 of the ASMP study, COB-140): the frame and the flap of every device
# symbol of a page follow the device's own alarms, read in one query for the whole page. The priorities
# map onto the four Cadre alert colours by rank (F053, COBD-044), as package colours its own alert
# levels (the module's `level-*` styles): Critical the critical colour, High alarm, Medium warning, Low
# caution, and Diagnostic no alert colour: a Diagnostic alarm draws no frame on a library symbol.
PRIORITY_STATUS = {"Critical": "critical", "High": "alarm", "Medium": "warning", "Low": "caution",
	"Diagnostic": ""}
ALERT_NONE = {"alert": False, "alertAny": False, "status": "alarm", "level": "level-high", "mode": "acked-active"}


def alert_states(session, devices):
	"""The alarm state of each device of `devices` ({key: device folder}): `alert` (a frame on a library
	symbol: an alarm of a priority with an alert colour), `alertAny` (any alarm, Diagnostic included: the
	module's frame, which colours `level-diagnostic` itself), `status` (alarm, warning, caution or
	critical), `level` (the module's `level-*`) and `mode`. The priority shown is that of the most severe
	unacknowledged active alarm, else of the most severe active one, else of the most severe cleared and
	unacknowledged one, with the mode `unacked-active`, `acked-active` or `unacked-rectified`. One query
	over every device's source patterns (`device_sources`) for the whole page."""
	keys = list(devices or {})
	out = dict((k, dict(ALERT_NONE)) for k in keys)
	patterns = dict((k, device_sources(session, devices[k])) for k in keys)
	every = [p for k in keys for p in patterns[k] if p != NO_MATCH]
	if not every:
		return out
	try:
		events = system.alarm.queryStatus(path=every, state=LIST_STATES)
	except Exception:
		return out
	best = dict((k, [None, None, None]) for k in keys)   # rank of: unacked active, active, cleared unacked
	for e in events:
		source = unicode(_accessor(e, "getSource"))
		priority = unicode(_accessor(e, "getPriority"))
		rank = PRIORITIES.index(priority) if priority in PRIORITIES else len(PRIORITIES) - 1
		cleared = bool(_accessor(e, "isCleared", False))
		acked = bool(_accessor(e, "isAcked", False))
		slot = 2 if cleared else (1 if acked else 0)
		if cleared and acked:
			continue
		for k in keys:
			if len([p for p in patterns[k] if _matches(p, source)]) > 0:
				if best[k][slot] is None or rank < best[k][slot]:
					best[k][slot] = rank
	for k in keys:
		for slot, mode in ((0, "unacked-active"), (1, "acked-active"), (2, "unacked-rectified")):
			rank = best[k][slot]
			if rank is not None:
				p = PRIORITIES[rank]
				status = PRIORITY_STATUS.get(p, "")
				out[k] = {"alert": status != "", "alertAny": True, "status": status or "alarm",
					"level": ALERT_TYPE.get(p, "level-low"), "mode": mode}
				break
	return out


def tag_id(source, devices=None):
	"""The device folder of an alarm, from its source path: 'prov:default:/tag:cadre_hmi_wtp/P502/
	fault:/alm:Fault' gives '[default]cadre_hmi_wtp/P502', the form of `selectedDevice`. With the
	device index, an alarm on a source tag outside the folders gives the device whose `sources`
	name it, so the alarm still opens its device."""
	s = unicode(source or "")
	try:
		for d in (devices or []):
			for pattern in (_entry_list(d, "sources") or []):
				if _matches(pattern, s):
					return unicode(d["folder"])
	except Exception:
		pass
	try:
		prov = s.split("prov:", 1)[1].split(":", 1)[0]
		tag = s.split(":/tag:", 1)[1].split(":/alm:", 1)[0]
	except Exception:
		return ""
	folder = tag.rsplit("/", 1)[0] if "/" in tag else tag
	return "[%s]%s" % (prov, folder)


def _raw(data, key):
	"""A value of event data by property name. The raw map's keys are property objects whose text
	is the name, so a lookup by the name string answers None (GF-35): match the keys by text."""
	try:
		values = data.getRawValueMap()
		for k in data.getProperties():
			if unicode(k) == key:
				return values.get(k)
	except Exception:
		pass
	return None


def _ms(data):
	try:
		return long(data.getTimestamp())
	except Exception:
		return None


def alert_record(event, devices=None):
	"""One alarm event as the package `Alert` record (dist/types.d.ts of the pinned package),
	times as epoch milliseconds: `id`, `tagId` (the device folder, `tag_id`), `source` (display path, else
	source), `text` (label, else name), `type` (from the priority), `time`, `acknowledged` (false
	or user and time), `active` (true or the clear time), `shelved` (false: queryStatus leaves
	shelved events out unless asked, IGW:22 section 3.1)."""
	src = _accessor(event, "getSource")
	active = _accessor(event, "getActiveData", None)
	rec = {"id": unicode(_accessor(event, "getId")), "tagId": tag_id(src, devices),
		"source": unicode(_accessor(event, "getDisplayPathOrSource") or src),
		"text": unicode(_accessor(event, "getLabel") or _accessor(event, "getName")),
		"type": ALERT_TYPE.get(unicode(_accessor(event, "getPriority")), "level-low"),
		"time": _ms(active) if active is not None else None,
		"acknowledged": False, "active": True, "shelved": False}
	notes = _accessor(event, "getNotes")
	if notes:
		rec["note"] = unicode(notes)
	if _accessor(event, "isAcked", False):
		data = _accessor(event, "getAckData", None)
		user = unicode(_raw(data, "ackUser") or "") if data is not None else ""
		rec["acknowledged"] = {"acknowledgedBy": user[4:] if user.startswith("usr:") else user,
			"acknowledgedAt": _ms(data) if data is not None else None}
	if _accessor(event, "isCleared", False):
		data = _accessor(event, "getClearedData", None)
		rec["active"] = {"rectifiedTime": _ms(data) if data is not None else None}
	return rec


def alarm_list(scope="*", source="", states=None, max_items=100, no_ack=False, session=None):
	"""The alarms of a device (`source`: its patterns from `device_sources`, as a list or as the
	comma separated text the faceplate hands the stock table) or of the project scope, as Alert
	records, most severe first, then newest first. With `no_ack`, every record carries the `Alert`
	field `noAck`: The package's list then draws its no-acknowledgement icon where a row would offer
	ACK (`render()` of alert-list-details.js in the pin), the display only list of COBD-025. With
	`session`, each record's `tagId` is looked up in the session's device index, so an alarm on a
	source tag names its device."""
	try:
		events = system.alarm.queryStatus(path=_paths(scope, source), state=states or LIST_STATES)
	except Exception:
		return []
	devices = None
	try:
		if session is not None:
			devices = session.custom.devices
	except Exception:
		pass
	out = [alert_record(e, devices) for e in events]
	out.sort(key=lambda r: (TYPE_RANK.index(r["type"]) if r["type"] in TYPE_RANK else 9, -(r["time"] or 0)))
	if no_ack:
		for r in out:
			r["noAck"] = True
	return out[:max_items]


def ack(ids, session=None, notes="Acknowledged from the alarm list", path="W8"):
	"""Acknowledge alarm events by id with the session's user (GF-21), write path W8 (a row's ACK)
	or W9 (ACK visible). Only the ids of alarms in the session's scope are acknowledged, so a crafted
	payload cannot reach another project's alarms (NOTE-COB-04 section 6.2 step 6). Returns the
	refusal, or the ids the gateway could not acknowledge."""
	if not allowed(session, path):
		return REFUSED
	ids = [unicode(i) for i in (ids or []) if i]
	if not ids:
		return []
	try:
		scope = session.custom.alarmScope
	except Exception:
		scope = None
	known = dict([(a["id"], a["tagId"]) for a in alarm_list(scope or "*", "", None, 1000, session=session)])
	ids = [i for i in ids if i in known]
	if not ids:
		return []
	failed = system.alarm.acknowledge(ids, notes, session_user(session))
	not_acked = [unicode(i) for i in (failed or [])]
	_relay_ack(session, path, [known[i] for i in ids if i not in not_acked])
	return failed


def _devices_of(session):
	"""The session's device index, else an empty list."""
	try:
		return list(session.custom.devices)
	except Exception:
		return []


# Alarm counts per node of the plant hierarchy (F047 of the ASMP study, COB-141): the active alarms of a
# node's own devices and of every node beneath it, by priority, for the badges of the breadcrumb and the
# menu (F046). One query over the session's alarm scope; each alarm goes to its device (`tag_id` over the
# device index, so an alarm on a source tag a device model names goes to its device), and the device to its
# node (`devices` of `session.custom.hierarchy`). The count is the library's until a native folder metric is
# proved on the gateway (probe E9, ASMP-009).
def _no_counts():
	out = dict((p, 0) for p in PRIORITIES)
	out.update({"total": 0, "unacked": 0})
	return out


def _hierarchy(session):
	try:
		return list(session.custom.hierarchy or [])
	except Exception:
		return []


def node_counts(session):
	"""{node id: {each priority: n, "total": n, "unacked": n}} for every node of the session's hierarchy."""
	nodes = _hierarchy(session)
	out = dict((unicode(n["id"]), _no_counts()) for n in nodes)
	if not nodes:
		return out
	owner, parent = {}, {}
	for n in nodes:
		parent[unicode(n["id"])] = unicode(n["parentId"] or "")
		for d in (n["devices"] or []):
			owner[unicode(d)] = unicode(n["id"])
	try:
		scope = session.custom.alarmScope
	except Exception:
		scope = "*"
	try:
		events = system.alarm.queryStatus(path=[scope or "*"], state=ACTIVE)
	except Exception:
		return out
	devices = _devices_of(session)
	for e in events:
		nid = owner.get(tag_id(_accessor(e, "getSource"), devices))
		priority = unicode(_accessor(e, "getPriority"))
		unacked = not bool(_accessor(e, "isAcked", False))
		seen = 0
		while nid and seen < 64:   # up to the root; a cycle cannot hold the loop
			c = out[nid]
			if priority in c:
				c[priority] += 1
			c["total"] += 1
			if unacked:
				c["unacked"] += 1
			nid = parent.get(nid)
			seen += 1
	return out


def crumbs(session, route):
	"""The breadcrumb of a page (F036): the nodes from the root to the page's own, each with its name, the
	route of its first page (empty for a node without one) and its counts (`node_counts`). Empty for a page
	that names no node."""
	nodes = _hierarchy(session)
	by_id = dict((unicode(n["id"]), n) for n in nodes)
	here = None
	for n in nodes:
		if len([p for p in (n["pages"] or []) if p["route"] == route]) > 0:
			here = n
	chain = []
	seen = 0
	while here is not None and seen < 64:
		chain.insert(0, here)
		here = by_id.get(unicode(here["parentId"] or ""))
		seen += 1
	if not chain:
		return []
	counts = node_counts(session)
	out = []
	for i, n in enumerate(chain):
		pages = list(n["pages"] or [])
		out.append({"name": unicode(n["name"]), "route": unicode(pages[0]["route"]) if pages else "",
			"counts": counts.get(unicode(n["id"]), _no_counts()), "first": i == 0})
	return out


def nav_items(session):
	"""The navigation menu's items with the counts of each item's node (F046); no counts for an item that
	names no node."""
	try:
		items = list(session.custom.nav["items"])
	except Exception:
		return []
	counts = node_counts(session)
	ids = dict((unicode(n["path"]), unicode(n["id"])) for n in _hierarchy(session))
	out = []
	for it in items:
		node = ""
		try:
			node = unicode(it["node"] or "")
		except Exception:
			pass
		out.append({"label": it["label"], "path": it["path"], "icon": it["icon"],
			"counts": counts.get(ids.get(node, ""), _no_counts())})
	return out


def _relay_ack(session, path, folders):
	"""Tell each device of `folders` whose device model lists ACK_MEMBER that one of its alarms was
	acknowledged (F049): true written through the checked writes, under the acknowledgement's path. A
	device without the member, the default, is told nothing. A relay the checked writes refuse leaves
	the acknowledgement made."""
	for d in sorted(set([unicode(f) for f in folders if f])):
		if ACK_MEMBER in (_entry_list(_device_entry(session, d), "members") or []):
			_checked_writes(session, path, d, [(ACK_MEMBER, True)])



# The module's alarm lists (COB-078): their events reach these through the component event scripts.
def _event_field(event, name, default=None):
	"""A field of a module component event's payload, read as an attribute (the corpus form,
	`event.clientX`), else as an item."""
	try:
		return getattr(event, name)
	except Exception:
		pass
	try:
		return event[name]
	except Exception:
		return default


def ack_event(event, session=None, path="W8"):
	"""The ACK (W8) and ACK visible (W9) events of the module's alarm lists: `event.ids` (COB-078)."""
	return ack([i for i in (_event_field(event, "ids") or []) if i], session, path=path)


# Ack selected and Ack all (L5, COB-166): the alarm lists' two buttons. A row is a record of the module's list (`id`,
# `acknowledged` false while unacknowledged), a row of the stock table (`eventId`, `isAcked`), or the id itself.
def _row_id(row):
	if isinstance(row, (str, unicode)):
		return unicode(row)
	for name in ("eventId", "id"):
		v = _event_field(row, name, None)
		if v:
			return unicode(v)
	return ""


def _row_unacked(row):
	if isinstance(row, (str, unicode)):
		return True
	acked = _event_field(row, "isAcked", None)
	if acked is not None:
		if isinstance(acked, (str, unicode)):		# the stock table on 8.3.6 gives "true" or "false"
			return acked.strip().lower() != "true"
		return not acked
	return _event_field(row, "acknowledged", False) is False


def unacked_ids(rows):
	"""The ids of the unacknowledged alarms among `rows`, in order and once each: what Ack all acknowledges."""
	out = []
	for r in (rows or []):
		i = _row_id(r)
		if i and _row_unacked(r) and i not in out:
			out.append(i)
	return out


def selected_ids(*groups):
	"""The ids of the rows or ids of the selection groups, once each: what Ack selected acknowledges."""
	out = []
	for g in groups:
		for r in (g or []):
			i = _row_id(r)
			if i and i not in out:
				out.append(i)
	return out


def ack_message(result):
	"""The line an acknowledgement leaves under the buttons: the refusal, how many the gateway could not acknowledge,
	or nothing."""
	if isinstance(result, (str, unicode)):
		return unicode(result)
	failed = len(result or [])
	return "" if failed == 0 else unicode(failed) + (" alarm" if failed == 1 else " alarms") + " could not be acknowledged"


def ack_listed(ids, session=None, path="W7"):
	"""Acknowledge the ids a list shows or has selected, write path `path` (W7 on the pages and the stock tables, W8 for
	Ack selected and W9 for Ack all on the panels), and answer the message to show (`ack_message`)."""
	return ack_message(ack(ids, session, "Acknowledged from the alarm list", path))


def _entry_local(entry):
	"""The `local` kind of a device index entry (a local assembly's `<Kind>`, NOTE-WFB-10 section 11.2 item 3), or None
	for a device that has none: what every opener of a device passes on to `select_device`."""
	try:
		return unicode(entry["local"] or "") or None
	except Exception:
		return None


def select_alarm_device(session, event):
	"""A row of the alarm panel: select the device whose folder raised the alarm, from the device
	index the generator writes (`session.custom.devices`), instruments included since COB-062. The
	record's `tagId` already names the device of an alarm on a source tag (`alarm_list` with the
	session, `tag_id`). A local device is selected with its local kind (section 11.2 item 5), else its
	faceplate would embed `Local//Home`. False when the alarm belongs to no device of the descriptors."""
	folder = unicode(_event_field(event, "tagId", "") or "")
	try:
		for d in session.custom.devices:
			if d["folder"] == folder:
				select_device(session, folder, d["kind"], d["title"], d["label"], local=_entry_local(d))
				return True
	except Exception:
		pass
	return False


# Interlocks and permissives (COB-079): the provisional contract of COB-PLAN-01 Tables 7 and 8, one
# condition per folder `<device>/ilk/Cnn/` and the summary in `<device>/ilk/`. Tags are found with
# `system.tag.exists` and read with `system.tag.readBlocking(paths)[i].value` (IGW:22 and its corpus),
# so a device without interlocks binds no missing tag.
ILK_SUMMARY = ["permitted", "interlocked", "bypassed", "unsatisfied", "resetRequired"]
ILK_MAX = 20


def interlock_rows(device_id, session=None):
	"""The rows of a device's Interlocks tab, [{'deviceId', 'cid', 'writable'}] for C01, C02 ... while
	the condition exists; empty for a device without interlocks. `writable` says whether the bypass
	may be written at all, which the row's Bypass follows: the device is one of the session's project
	and its device model does not mark `ilk/<cid>/bypassed` read only. False without a session."""
	rows = []
	d = (device_id or "").strip()
	rule = _write_rule(session, d)
	for n in range(1, ILK_MAX + 1):
		cid = "C%02d" % n
		try:
			if not d or not system.tag.exists(d + "/ilk/" + cid + "/ok"):
				break
		except Exception:
			break
		rows.append({"deviceId": d, "cid": cid, "writable": _may(rule, "ilk/" + cid + "/bypassed")})
	return rows


def interlock_summary(device_id, session=None):
	"""The summary of `<device>/ilk/`: present, permitted, interlocked, bypassed, unsatisfied,
	resetRequired, and `holding`, the conditions that hold the device (not met, or latched and waiting
	for a reset), which the Interlocks tab counts. For a device without interlocks: present False,
	permitted True, and nothing is read. `resetWritable` says whether the reset may be written at all
	(the session's device, `ilk/resetAt` not marked read only by its model), which the tab's Reset
	follows; False without a session."""
	out = {"present": False, "permitted": True, "interlocked": False, "bypassed": False, "unsatisfied": 0,
		"resetRequired": False, "holding": 0, "resetWritable": False}
	d = (device_id or "").strip()
	try:
		if not d or not system.tag.exists(d + "/ilk/permitted"):
			return out
		values = system.tag.readBlocking([d + "/ilk/" + m for m in ILK_SUMMARY])
		out["present"] = True
		out["resetWritable"] = _writable(session, d, "ilk/resetAt")
		for m, qv in zip(ILK_SUMMARY, values):
			if qv.value is not None:
				out[m] = int(qv.value) if m == "unsatisfied" else bool(qv.value)
		out["holding"] = out["unsatisfied"]
		if out["resetRequired"]:
			rows = interlock_rows(d)
			paths = [d + "/ilk/" + r["cid"] + "/resetRequired" for r in rows]
			paths = [p for p in paths if system.tag.exists(p)]
			out["holding"] += len([qv for qv in system.tag.readBlocking(paths) if qv.value])
	except Exception as e:
		out["error"] = unicode(e)[:200]
	return out


# The members each faceplate write path may write through `command` (NOTE-COB-04 Tables 2 and 7); W12 to
# W15 are the controller's setpoint, loop mode, manual output and tuning.
PATH_MEMBERS = {"W1": ["cmd"], "W2": ["mode"], "W3": ["speedSp"], "W4": ["hiHiLimit", "hiLimit", "loLimit", "loLoLimit",
	"hiHiLimitDelay", "hiLimitDelay", "loLimitDelay", "loLoLimitDelay"],
	"W5": ["fault"], "W12": ["sp"], "W13": ["manual"], "W14": ["manOut"], "W15": ["gain", "ti", "td"]}
# Maintenance functions (wiki page 13 section 9), held in the device's subfolder `mnt/`. The force is a
# pair of flags, or a mode and a value; `force` and `error_mask` write them (W16, W17), never `command`.
MNT_FORCE_PAIR = ["mnt/forceOn", "mnt/forceOff"]
MNT_FORCE_MODE = ["mnt/forceMode", "mnt/forceValue"]
MNT_MASK = "mnt/errorMask"
MNT_FLAGS = [("mnt/simulated", "Simulated"), ("mnt/alarmSuppress", "Alarms suppressed"), ("mnt/manualMode", "Manual mode")]
FUNCTION_MEMBERS = {"W16": ["mnt/forceOn", "mnt/forceOff", "mnt/forceMode", "mnt/forceValue"], "W17": ["mnt/errorMask"],
	"W18": ["trigger", "cmdStart", "cmdStop", "cmdReset", "cmdServiceDone", "cmdInService", "cmdOutOfService",
		"cmdEnable", "cmdDisable"], "W6": ["alarmAck"], "W8": ["alarmAck"], "W9": ["alarmAck"]}
# The controller acknowledgement bit (F049 of the ASMP study, COBD-044: optional per device, off by
# default): a device whose device model lists `alarmAck` (Boolean, `write`) is told of an acknowledgement
# of one of its alarms made through `cadre.hmi` (the top bar, W6; the module's alarm menu, W8 and W9):
# true is written, under the path of the acknowledgement, and the controller returns it to false. The
# stock alarm table acknowledges by itself (W7, GF-40), so no relay follows an acknowledgement made there.
ACK_MEMBER = "alarmAck"
# A pulse command (wiki page 13 section 9.7) is a Boolean member that `pulse` writes true (W18) and the
# plant, or a simulation, returns to false: the cycle command of a sequence, and since COB-158 the generator's
# Start, Stop, Reset and Service completed and the sequence's In service, Out of service, Enable and Disable. Its
# members are those of FUNCTION_MEMBERS under this path, so `command` writes none of them.
PULSE_PATH = "W18"
# A configuration member (finding F010 of the ASMP study, COBD-045) is a number a device model marks
# `config`, under the device's subfolder `cfg/`, with its caption, unit, bounds and format: the
# Config rows of the faceplate, written by `configure` (W19) within the bounds the model gives.
CONFIG_PATH = "W19"
CONFIG_PREFIX = "cfg/"
# The value rules of `command`: the paths that take a number, and the range of a member that has one
# ([low, high], None for no bound). The setpoint fields take their entry bounds from the same table
# (`framework._setpoint`), so the field and the rule cannot differ. The manual output (W14) is written
# only while `<device>/manual` reads true.
NUMBER_PATHS = ["W3", "W4", "W12", "W14", "W15"]
MEMBER_BOUNDS = {"speedSp": [0, 100], "manOut": [0, 100], "ti": [0, None], "td": [0, None],
	"hiHiLimitDelay": [0, 3600], "hiLimitDelay": [0, 3600], "loLimitDelay": [0, 3600], "loLoLimitDelay": [0, 3600]}
# An alarm limit's on-delay (F028 of the ASMP study, COB-140): the member `<limit>Delay`, in seconds,
# which the alarm's `timeOnDelaySeconds` follows (`tools/hmi/alarms.py`); W4 writes it as it writes
# the limit, within 0 to 3600 s.
DELAY_SUFFIX = "Delay"


def _device_of_session(session, device_id):
	"""The device folder, when it is a device of the session's project (the generator's device index).
	An identifier that is not text (a number, a list) names no device."""
	try:
		d = (device_id or "").strip()
		return d if d and d in [x["folder"] for x in session.custom.devices] else None
	except Exception:
		return None


def _model_built(session):
	"""A device model built the session's project (`session.custom.deviceModel`, written by the
	generator): every device of its index then carries a `write` list, and one that lacks it has
	lost it."""
	try:
		return bool(session.custom.deviceModel)
	except Exception:
		return False


def _rule_of(session, entry):
	"""The write rule of a device from its entry of the device index (None for a folder that is not
	in it): the device is in the index, its `write` list (None without one), and whether a device model
	built the project."""
	return (entry is not None, _entry_list(entry, "write"), _model_built(session))


def _write_rule(session, device_id):
	"""What the device model says of writing a device, found in one pass over the device index
	(`_rule_of`). `_may` answers for a member from it, so a caller that asks for many members looks the
	device up once."""
	return _rule_of(session, _device_entry(session, device_id))


def _may(rule, member):
	"""The rule of `_write_rule` lets `member` be written: the device is the project's and, where its
	entry carries a `write` list, the member is in it. A device without the list keeps the rule of its
	write path alone in a project built without a device model, and may write nothing in one built
	with a model: the list is then missing, not absent by design."""
	known, listed, strict = rule
	if not known:
		return False
	if listed is None:
		return not strict
	return member in listed


def _writable(session, device_id, member):
	"""The device model lets the session's project write `member` of the device (`_write_rule`, `_may`)."""
	return _may(_write_rule(session, (device_id or "").strip()), member)


def _path_of(member):
	"""The write path that writes a member, else None."""
	for table in (PATH_MEMBERS, FUNCTION_MEMBERS):
		for w in WRITE_PATHS:
			if member in table.get(w, []):
				return w
	return None


def _written(result, names):
	"""The refusal of a write the gateway did not make, else an empty string. `writeBlocking` does not
	raise: it answers one quality per path, `Good`, or for example `Bad_ReadOnly` for an expression tag
	and `Bad_NotFound` for a reference tag whose source is missing (measured, GF-47, GF-49, GF-50). The
	quality is read as text, as `_good` reads it; an answer that cannot be read counts as not written."""
	bad = []
	for i, name in enumerate(names):
		try:
			q = unicode(result[i])
		except Exception:
			q = "no answer"
		if not q.startswith("Good"):
			bad.append("%s (%s)" % (name, q.split("(")[0]))
	if bad:
		return "Refused: the gateway did not write " + ", ".join(bad)
	return ""


def _number(value):
	"""`value` as a float where it is a number: not null, a Boolean, text or a list, and not NaN or an
	infinity; else None."""
	if value is None or isinstance(value, bool) or hasattr(value, "split"):
		return None
	try:
		n = float(value)
	except Exception:
		return None
	if n != n or n in (float("inf"), float("-inf")):
		return None
	return n


def _reads_true(path):
	"""The tag exists and reads true."""
	try:
		return bool(system.tag.exists(path) and system.tag.readBlocking([path])[0].value)
	except Exception:
		return False


# Ownership by mode (COBD-044, the study's F005 option B): a device model may give a device its modes,
# each a value of the member `mode`, a name and an owner. The owner decides which write paths the
# device's commands may use (OWNER_PATHS over the paths of OWNER_GATED); the mode command (W2) moves
# ownership: Take control writes the operator's mode, Release the program's, Maintenance the
# maintenance owner's. Nothing moves a device the local station holds. A device without modes keeps
# the rules of its write paths alone.
OWNERS = ["program", "operator", "maintenance", "local"]
OWNER_TEXT = {"program": "the program", "operator": "the operator", "maintenance": "maintenance",
	"local": "the local station"}
OWNER_LABEL = {"program": "Program", "operator": "Operator", "maintenance": "Maintenance", "local": "Local station"}
OWNER_GATED = ["W1", "W3", "W5", "W16", "W17", "W18", "W19"]
OWNER_PATHS = {"program": [], "operator": ["W1", "W3", "W5", "W18"],
	"maintenance": ["W1", "W3", "W5", "W16", "W17", "W18", "W19"], "local": []}


def _modes(entry):
	"""The device's modes from its entry of the device index ([{'value', 'name', 'owner'}], as the
	generator writes them from the device model), else None: the device is not gated by ownership."""
	try:
		modes = entry["modes"]
	except Exception:
		return None
	out = []
	try:
		for m in modes:
			out.append({"value": int(m["value"]), "name": unicode(m["name"]), "owner": unicode(m["owner"])})
	except Exception:
		return None
	return out or None


def _whole(value):
	"""`value` as a whole number where it is one, not a Boolean; else None."""
	if isinstance(value, bool):
		return None
	n = _number(value)
	if n is None or n != int(n):
		return None
	return int(n)


def _mode_now(device, modes):
	"""The device's current mode among `modes`: the one whose value the member `mode` reads, else
	None (the member is missing, of bad quality, or reads a value that is not one of the modes)."""
	try:
		qv = system.tag.readBlocking([device + "/mode"])[0]
		if not _good(qv):
			return None
		v = _whole(qv.value)
	except Exception:
		return None
	for m in modes:
		if m["value"] == v:
			return m
	return None


def _title_of(entry, device):
	"""The identifier a refusal names: the device's title in the index, else its folder's last name."""
	try:
		if entry["title"]:
			return unicode(entry["title"])
	except Exception:
		pass
	return device.split("/")[-1]


def _owner_refusal(entry, device, path, writes):
	"""The refusal of a write the device's owner does not let `path` make, else an empty string. A
	device without modes is not gated. A path of OWNER_GATED is refused unless the current mode's
	owner lists it; the mode command (W2) is refused while the local station holds the device, and for
	a value that is not one of the device's modes the operator may choose (owned by the program, the
	operator or maintenance). A mode the member does not read as one of the device's refuses both."""
	modes = _modes(entry)
	if modes is None or (path not in OWNER_GATED and path != "W2"):
		return ""
	title = _title_of(entry, device)
	now = _mode_now(device, modes)
	if now is None:
		return "Refused: the mode of %s is not one of its modes" % title
	if path == "W2":
		if now["owner"] == "local":
			return "Refused: %s is held by the local station (%s)" % (title, now["name"])
		for m, v in writes:
			target = [x for x in modes if x["value"] == _whole(v) and x["owner"] != "local"]
			if not target:
				return "Refused: %s is not a mode the operator may choose" % unicode(v)
		return ""
	if path not in OWNER_PATHS.get(now["owner"], []):
		return "Refused: %s is owned by %s (%s)" % (title, OWNER_TEXT.get(now["owner"], now["owner"]), now["name"])
	return ""


def ownership(entry, device):
	"""What a faceplate shows of a device's ownership, part of `device_read`: `owned` (the device has
	modes), `owner` {name, owner, text}, `allowed` {path: the owner lets the path write}, `reason` (why
	a gated command is disabled, else empty), and for each move the mode command may make
	(`take`, `release`, `maintain`) whether it is offered now and the mode's value and name."""
	out = {"owned": False, "owner": {"name": "", "owner": "", "text": ""}, "allowed": {}, "reason": "",
		"take": {"offered": False, "value": 0, "name": ""}, "release": {"offered": False, "value": 0, "name": ""},
		"maintain": {"offered": False, "value": 0, "name": ""}}
	for p in OWNER_GATED:
		out["allowed"][p] = True
	modes = _modes(entry)
	if modes is None:
		return out
	out["owned"] = True
	title = _title_of(entry, device)
	now = _mode_now(device, modes)
	if now is None:
		out["owner"] = {"name": "Unknown", "owner": "", "text": "Unknown"}
		out["reason"] = "The mode of %s is not one of its modes" % title
		for p in OWNER_GATED:
			out["allowed"][p] = False
		return out
	who = now["owner"]
	out["owner"] = {"name": now["name"], "owner": who, "text": OWNER_LABEL.get(who, who)}
	for p in OWNER_GATED:
		out["allowed"][p] = p in OWNER_PATHS.get(who, [])
	if who in ("program", "local"):
		out["reason"] = "Owned by %s (%s)" % (OWNER_TEXT.get(who, who), now["name"])

	def first(owner):
		found = [m for m in modes if m["owner"] == owner]
		return found[0] if found else None
	moves = (("take", "operator", ("program", "maintenance")), ("release", "program", ("operator", "maintenance")),
		("maintain", "maintenance", ("operator",)))
	for key, target, sources in moves:
		m = first(target)
		if m is not None and who in sources:
			out[key] = {"offered": True, "value": m["value"], "name": m["name"]}
	return out


def command(session, path, device_id, member, value):
	"""The checked write of a faceplate (NOTE-COB-04 section 6.2 step 3): refused unless the session's
	user holds a role the write path permits (COBD-024), the member is one the path writes, the value
	suits the path (the value rules above; a fault reset, W5, only clears), the device is one of the
	project's, and the device model does not mark the member read only. Returns an empty string, or
	the refusal, which the faceplate shows; a refused command leaves the tag as it was. A write the
	gateway does not make is answered as a refusal too. The session is the only identity: a crafted
	call cannot name a user or a role. A configuration member (W19) goes to `configure`, so that the
	setpoint row writes it as it writes any other."""
	if path == CONFIG_PATH:
		return configure(session, device_id, member, value)
	# the faceplate's Confirm row (F029) makes every pending write through this one call; the paths with
	# a function of their own go to it, which checks as it always has
	if path == "W11":
		return reset_interlocks(session, device_id)
	if path == "W16":
		return force(session, device_id, value)
	if path == "W17":
		return error_mask(session, device_id, value)
	if path == PULSE_PATH:   # as `_checked_writes`: no call of the pulse path writes anything but true
		if value is not True:
			return "Refused: a pulse command only writes true"
		return pulse(session, device_id, member)
	if not allowed(session, path):
		return REFUSED
	if member not in PATH_MEMBERS.get(path, []):
		return "Refused: %s does not write %s" % (path, member)
	if path == "W5" and value:
		return "Refused: a fault reset only clears the fault"
	if path in NUMBER_PATHS:
		number = _number(value)
		if number is None:
			return "Refused: %s takes a number" % member
		low, high = MEMBER_BOUNDS.get(member, [None, None])
		if (low is not None and number < low) or (high is not None and number > high):
			return "Refused: %s is outside its range" % member
	d = _device_of_session(session, device_id)
	if d is None:
		return "Refused: not a device of this project"
	if not _writable(session, d, member):
		return "Refused: %s is read only on this device" % member
	if path == "W14" and not _reads_true(d + "/manual"):
		return "Refused: the loop is not in manual"
	if path == "W1" and value and not start_permitted(d):
		return "Refused: interlocks hold the device"
	return _checked_writes(session, path, d, [(member, value)])


def _carries(device, members):
	"""The device folder carries every one of `members`."""
	try:
		return len([m for m in members if not system.tag.exists(device + "/" + m)]) == 0
	except Exception:
		return False


def _checked_writes(session, path, device_id, writes):
	"""The one place `cadre.hmi` writes a member of a device: `writes`, [(member, value)], for write
	path `path`. It carries every check itself, so that no caller can leave one out: the role of the
	path, the device in the session's index, each member one the path writes, and none the device
	model marks read only; and on the pulse path no value but true, so that no call of it returns a
	pulse member to false. Nothing is written unless every check holds for every member. The members
	are then written one at a time in their order, and the first the gateway does not write ends the
	call with its refusal (`_written`), so a later member is never written after an earlier one
	failed. `writeBlocking` answers a quality and does not raise (GF-47, GF-49); were it to raise, the
	exception would leave this function with no later member written. Returns an empty string, or the
	refusal."""
	if not allowed(session, path):
		return REFUSED
	d = (device_id or "").strip()
	rule = _write_rule(session, d)
	if not d or not rule[0]:
		return "Refused: not a device of this project"
	members = PATH_MEMBERS.get(path, []) + FUNCTION_MEMBERS.get(path, [])
	if path == CONFIG_PATH:   # the configuration members the device model gives the device (F010)
		members = [c["member"] for c in _entry_config(_device_entry(session, d))]
	for m, v in writes:
		if m not in members:
			return "Refused: %s does not write %s" % (path, m)
		if not _may(rule, m):
			return "Refused: %s is read only on this device" % m
		if path == PULSE_PATH and v is not True:
			return "Refused: a pulse command only writes true"
	refusal = _owner_refusal(_device_entry(session, d), d, path, writes)   # ownership by mode (COBD-044)
	if refusal:
		return refusal
	for m, v in writes:
		msg = _written(system.tag.writeBlocking([d + "/" + m], [v]), [m])
		if msg:
			return msg
	return ""


def _entry_config(entry):
	"""The configuration rows a device model gives a device (`config` of its index entry): a list of
	{member, caption, unit, minimum, maximum, format}, empty for a device without them."""
	try:
		return [c for c in entry["config"] if unicode(c["member"]).startswith(CONFIG_PREFIX)]
	except Exception:
		return []


def config_rows(session, device_id, enabled=True):
	"""The Config rows of a device: one `Faceplate/SetpointRow` instance per configuration member of
	its entry, written through W19 within its bounds. A row is enabled where `enabled` (the owner
	allows W19) and the device model lets the member be written."""
	d = (device_id or "").strip()
	entry = _device_entry(session, d)
	rule = _rule_of(session, entry)
	rows = []
	for c in _entry_config(entry):
		rows.append({"deviceId": d, "member": c["member"], "label": c.get("caption") or c["member"],
			"path": CONFIG_PATH, "format": c.get("format") or "0.0", "minimum": c.get("minimum"),
			"maximum": c.get("maximum"), "unit": c.get("unit") or "",
			"enabled": bool(enabled) and _may(rule, c["member"])})
	return rows


def configure(session, device_id, member, value):
	"""A configuration value (write path W19, the admin role, COBD-024; F010): refused unless the
	member is one the device model marks `config` for the device, the value is a number within the
	bounds the model gives it, and the checked write allows it (the device model's write list and the
	device's owner, COBD-044). Returns an empty string, or the refusal."""
	if not allowed(session, CONFIG_PATH):
		return REFUSED
	d = _device_of_session(session, device_id)
	if d is None:
		return "Refused: not a device of this project"
	spec = None
	for c in _entry_config(_device_entry(session, d)):
		if c["member"] == member:
			spec = c
	if spec is None:
		return "Refused: %s is not a configuration member of this device" % member
	number = _number(value)
	if number is None:
		return "Refused: %s takes a number" % member
	low, high = spec.get("minimum"), spec.get("maximum")
	if (low is not None and number < low) or (high is not None and number > high):
		return "Refused: %s is outside its range" % member
	return _checked_writes(session, CONFIG_PATH, d, [(member, value)])


def force(session, device_id, action):
	"""The Maintenance tab's force (write path W16, the admin role, COBD-024): `action` is 'on',
	'off' or 'auto'. A device with `mnt/forceMode` and `mnt/forceValue` gets the value, then the mode
	(automatic clears the mode and leaves the value); one with `mnt/forceOn` and `mnt/forceOff` gets
	the flag that clears, then the flag that sets. Each member is a write of its own, and the second is
	made only when the gateway made the first, so a write that fails leaves the device as it was or
	automatic, never forced the other way and never with both flags true. Refused without the role,
	for a device that is not the project's or carries neither pair, and, whatever the action, where
	the device model marks either member of the pair read only (the function is then not the
	project's to write: `writable.force` of `device_read` states the same rule). Returns an empty
	string, or the refusal."""
	if not allowed(session, "W16"):
		return REFUSED
	if action not in ("on", "off", "auto"):
		return "Refused: no such force action"
	d = _device_of_session(session, device_id)
	if d is None:
		return "Refused: not a device of this project"
	if _carries(d, MNT_FORCE_MODE):
		pair = MNT_FORCE_MODE
		mode, value = pair
		writes = {"on": [(value, True), (mode, True)], "off": [(value, False), (mode, True)],
			"auto": [(mode, False)]}[action]
	elif _carries(d, MNT_FORCE_PAIR):
		pair = MNT_FORCE_PAIR
		on, off = pair
		writes = {"on": [(off, False), (on, True)], "off": [(on, False), (off, True)],
			"auto": [(on, False), (off, False)]}[action]
	else:
		return "Refused: this device has no force"
	rule = _write_rule(session, d)
	for m in pair:
		if not _may(rule, m):
			return "Refused: %s is read only on this device" % m
	return _checked_writes(session, "W16", d, writes)


def error_mask(session, device_id, value):
	"""The Maintenance tab's object error mask (write path W17, the admin role, COBD-024): true masks
	the device's object error, false returns it to automatic. Refused as `force` is. Returns an empty
	string, or the refusal."""
	if not allowed(session, "W17"):
		return REFUSED
	d = _device_of_session(session, device_id)
	if d is None:
		return "Refused: not a device of this project"
	if not _carries(d, [MNT_MASK]):
		return "Refused: this device has no object error mask"
	return _checked_writes(session, "W17", d, [(MNT_MASK, bool(value))])


def pulse(session, device_id, member):
	"""A pulse command of a faceplate (write path W18, the admin role, COBD-024): true is written to
	the pulse member and nothing else is written; the plant, or a simulation, returns the member to
	false. Refused without the role, for a member that is not a pulse member of the path (`command`
	writes none of them and `_checked_writes` writes one nothing but true, so no call writes one
	false), for a device that is not the project's or does not carry the member, and where the device
	model does not mark the member writable. The role is asked first, so a session without it learns
	nothing of a device or a member. The function does not ask the device's kind: in a project built
	without a device model the rule of the write path stands alone, and any device of the index whose
	folder carries the member is pulsed; with a device model the `write` list decides, and gate G7
	devices lets only a kind with the pulse member mark it. A write the gateway does not make is
	answered as a refusal. Returns an empty string, or the refusal."""
	if not allowed(session, PULSE_PATH):
		return REFUSED
	m = unicode(member or "")
	if m not in FUNCTION_MEMBERS.get(PULSE_PATH, []):
		return "Refused: %s is not a pulse command" % (m or "this")
	d = _device_of_session(session, device_id)
	if d is None:
		return "Refused: not a device of this project"
	if not _carries(d, [m]):
		return "Refused: this device has no %s" % m
	return _checked_writes(session, PULSE_PATH, d, [(m, True)])


def bypass(session, device_id, cid, value):
	"""Bypass a condition, or remove its bypass (write path W10, the admin role, COBD-024): only a
	condition whose `bypassable` is true. Returns an empty string, or the refusal."""
	if not allowed(session, "W10"):
		return REFUSED
	d = _device_of_session(session, device_id)
	if d is None:
		return "Refused: not a device of this project"
	base = d + "/ilk/" + unicode(cid or "")
	if not system.tag.exists(base + "/bypassable") or not system.tag.readBlocking([base + "/bypassable"])[0].value:
		return "Refused: this condition may not be bypassed"
	if not _writable(session, d, "ilk/" + unicode(cid or "") + "/bypassed"):
		return "Refused: the bypass is read only on this device"
	return _written(system.tag.writeBlocking([base + "/bypassed"], [bool(value)]), ["the bypass"])


def reset_interlocks(session, device_id):
	"""The Interlocks tab's Reset (COBD-023), write path W11 (the admin role, COBD-024): the time of the
	request, written to `<device>/ilk/resetAt`. A latched condition that is met again, and was last not
	met before this time, releases the device; one whose cause persists stays latched. Returns an empty
	string, or the refusal."""
	if not allowed(session, "W11"):
		return REFUSED
	d = _device_of_session(session, device_id)
	path = (d or "") + "/ilk/resetAt"
	if d is None or not system.tag.exists(path):
		return "Refused: no interlocks to reset"
	if not _writable(session, d, "ilk/resetAt"):
		return "Refused: the reset is read only on this device"
	return _written(system.tag.writeBlocking([path], [system.date.toMillis(system.date.now())]), ["the reset"])


def start_permitted(device_id):
	"""Start is refused while a device with interlocks is not permitted or is interlocked (COB-079
	rule 1); a device without interlocks is always permitted."""
	s = interlock_summary(device_id)
	return (not s["present"]) or (s["permitted"] and not s["interlocked"])


# What a faceplate reads of its device (wiki page 13 section 9). A device carries the members its source
# has and no others, so a faceplate binds no member's tag: it polls `device_read`, which looks for each
# member before reading it, and shows a row, a command group or a tab only while its member exists. The
# typed default of a member stands in where the device lacks it, so no expression meets null.
MEMBER_DEFAULTS = {"state": False, "cmd": False, "mode": 0, "speed": 0.0, "speedSp": 0.0, "fault": False,
	"level": 0.0, "value": 0.0, "sp": 0.0, "out": 0.0, "manual": False, "manOut": 0.0, "gain": 0.0, "ti": 0.0,
	"td": 0.0, "mnt/forceOn": False, "mnt/forceOff": False, "mnt/forceMode": False, "mnt/forceValue": False,
	"mnt/errorMask": False, "mnt/simulated": False, "mnt/alarmSuppress": False, "mnt/manualMode": False,
	"step": 0, "stepText": "", "trigger": False,
	"runText": "", "switchText": "", "faultCode": 0, "engineSpeed": 0.0, "voltageLL": 0.0, "fuelLevel": 0.0,
	"fuelLowLimit": 0.0, "startDelay": 0.0, "stopDelay": 0.0, "timeLeft": 0.0, "runHours": 0.0, "startsToday": 0,
	"startsYesterday": 0, "serviceHours": 0.0, "oilPressureOk": False, "readyToRun": False, "genComm": False,
	"plcComm": False, "inService": False, "enabled": False, "normal": False, "remoteAuto": False, "oos": False,
	"badValue": False, "ioFault": False, "overRange": False, "underRange": False, "rangeLo": 0.0, "rangeHi": 0.0,
	"cmdStart": False, "cmdStop": False, "cmdReset": False, "cmdServiceDone": False, "cmdInService": False,
	"cmdOutOfService": False, "cmdEnable": False, "cmdDisable": False}


def _key(member):
	"""A member's key in the structure of `device_read`: a property name cannot hold the slash."""
	return member.replace("/", "_")


def _good(qv):
	"""The qualified value's quality is good. The quality reads as text, 'Good', or for example
	'Bad_NotFound("Path ... not found.")' for a reference tag whose source is missing (measured by
	experiment E6, GF-46 and GF-50)."""
	try:
		return unicode(qv.quality).startswith("Good")
	except Exception:
		return True


def _typed(value, default):
	"""`value` in the type of the member's default; the default where it cannot be."""
	try:
		if value is None:
			return default
		if isinstance(default, bool):
			return bool(value)
		if isinstance(default, int):
			return int(value)
		if isinstance(default, float):
			return float(value)
		return unicode(value)
	except Exception:
		return default


def _force_state(has, value):
	"""The force of a device: '' without the function, else 'auto', 'on' or 'off', from the mode and
	the value where the device has them, else from the pair of flags."""
	if has.get("mnt_forceMode") and has.get("mnt_forceValue"):
		if not value["mnt_forceMode"]:
			return "auto"
		return "on" if value["mnt_forceValue"] else "off"
	if has.get("mnt_forceOn") and has.get("mnt_forceOff"):
		if value["mnt_forceOn"]:
			return "on"
		return "off" if value["mnt_forceOff"] else "auto"
	return ""


def _captions(entry):
	"""The captions of a device's pulse members, {member: caption}, from the `pulses` a device model
	adds to the device's index entry ([{'member', 'caption'}]); empty without them."""
	out = {}
	try:
		for p in entry["pulses"]:
			if p["caption"]:
				out[unicode(p["member"])] = unicode(p["caption"])
	except Exception:
		pass
	return out


def device_read(session, device_id, members):
	"""Everything a faceplate shows of a device, read in one call and polled once a second:

	  has       member key -> the device carries the member (`system.tag.exists`)
	  value     member key -> its value, the typed default of MEMBER_DEFAULTS where it is absent
	  bad       the present members whose quality is not good
	  quality   the line the faceplate shows for them, 'Bad quality: state, fault', else empty: a
				polled value draws no quality overlay, so the faceplate says it in words
	  writable  member key -> the member exists, a write path writes it, and the device model does not
				mark it read only: its control is shown
	  write     member key -> writable, and the session's user holds the path's role: its control is
				enabled (advisory; the checked functions refuse on their own)
	  mnt       the device carries a row of the Maintenance tab: a whole force, the object error mask
				or a flag (half a force alone is no row, and no tab)
	  force     '' or 'auto', 'on', 'off'; `writable.force` and `write.force` cover its members
	  pulses    member key -> the caption of the button of each pulse member (W18) among `members`:
				the caption the device model gives it, else the member's name
	  config    the count of the device's configuration rows (`config_rows`, W19)
	  owned, owner, allowed, reason, take, release, maintain
				the device's ownership by mode (`ownership`); a device without modes reads owned
				false and every gated path allowed

	A member's key is its name with the slash of `mnt/` written as an underscore."""
	names = [unicode(m) for m in (members or [])]
	out = {"has": {}, "value": {}, "bad": [], "quality": "", "writable": {"force": False},
		"write": {"force": False}, "mnt": False, "force": "", "pulses": {}, "config": 0}
	out.update(ownership(None, ""))
	for m in names:
		k = _key(m)
		out["has"][k] = False
		out["value"][k] = MEMBER_DEFAULTS.get(m, 0.0)
		out["writable"][k] = False
		out["write"][k] = False
		if m in FUNCTION_MEMBERS.get(PULSE_PATH, []):
			out["pulses"][k] = m
	d = (device_id or "").strip()
	if not d:
		return out
	present = []
	for m in names:
		try:
			if system.tag.exists(d + "/" + m):
				present.append(m)
		except Exception:
			pass
	if not present:
		return out
	try:
		values = system.tag.readBlocking([d + "/" + m for m in present])
	except Exception as e:
		out["quality"] = "Bad quality: " + unicode(e)[:120]
		return out
	entry = _device_entry(session, d)   # one pass over the device index for the whole poll
	rule = _rule_of(session, entry)
	out["config"] = len(_entry_config(entry))
	captions = _captions(entry)
	for k in out["pulses"]:
		out["pulses"][k] = captions.get(out["pulses"][k]) or out["pulses"][k]
	can = {}
	for m, qv in zip(present, values):
		k = _key(m)
		out["has"][k] = True
		out["value"][k] = _typed(qv.value, out["value"][k])
		if not _good(qv):
			out["bad"].append(m)
		path = _path_of(m)
		if path is not None and path not in can:
			can[path] = allowed(session, path)
		out["writable"][k] = path is not None and _may(rule, m)
		out["write"][k] = out["writable"][k] and can[path]
	out["force"] = _force_state(out["has"], out["value"])
	rows = [MNT_MASK] + [m for m, _text in MNT_FLAGS]
	out["mnt"] = bool(out["force"]) or len([m for m in present if m in rows]) > 0
	if out["force"]:
		pair = MNT_FORCE_MODE if out["has"].get("mnt_forceMode") and out["has"].get("mnt_forceValue") else MNT_FORCE_PAIR
		out["writable"]["force"] = len([m for m in pair if not out["writable"][_key(m)]]) == 0
		out["write"]["force"] = out["writable"]["force"] and allowed(session, "W16")
	if out["bad"]:
		out["quality"] = "Bad quality: " + ", ".join(out["bad"])
	out.update(ownership(entry, d))
	return out


# Analogue instruments (COB-062): limits as setpoints, and the trend over the tag history (COB-064).
# Times come from `system.date.now`, `addHours` and `toMillis` (IGW:22).
LIMITS = [("hiHiLimit", "High high limit"), ("hiLimit", "High limit"), ("loLimit", "Low limit"),
	("loLoLimit", "Low low limit")]


def device_unit(session, device_id):
	"""The engineering unit of a device from the generator's device index, else empty."""
	try:
		for d in session.custom.devices:
			if d["folder"] == device_id:
				return unicode(d["unit"] or "")
	except Exception:
		pass
	return ""


def limit_rows(device_id, value_member=None, session=None):
	"""The limit members a device carries, in order: [{'deviceId', 'member', 'label', 'writable'}].
	Only the limits that exist are listed, so no faceplate binds a missing tag; with `value_member`,
	none is listed for a device without that member, which each row binds beside its limit.
	`writable` says whether the limit may be written at all, which the row's field follows: the device
	is one of the session's project and its device model does not mark the limit read only. False
	without a session."""
	rows = []
	d = (device_id or "").strip()
	rule = _write_rule(session, d)
	try:
		if value_member and not (d and system.tag.exists(d + "/" + value_member)):
			return rows
	except Exception:
		return rows
	for member, label in LIMITS:
		try:
			if d and system.tag.exists(d + "/" + member):
				rows.append({"deviceId": d, "member": member, "label": label, "writable": _may(rule, member)})
		except Exception:
			pass
	return rows


def delay_rows(device_id, session=None):
	"""The delay of each limit a device carries the delay of (F028): one `Faceplate/SetpointRow` instance
	per `<limit>Delay` member, written through W4 within its bounds, in the order of LIMITS. Only the
	delays that exist are listed, so no faceplate binds a missing tag."""
	rows = []
	d = (device_id or "").strip()
	rule = _write_rule(session, d)
	for member, label in LIMITS:
		m = member + DELAY_SUFFIX
		try:
			if d and system.tag.exists(d + "/" + m):
				low, high = MEMBER_BOUNDS.get(m, [0, None])
				rows.append({"deviceId": d, "member": m, "label": label.replace(" limit", "") + " delay (s)",
					"path": "W4", "format": "0", "minimum": low, "maximum": high, "unit": "s",
					"enabled": _may(rule, m)})
		except Exception:
			pass
	return rows


# Members whose trend is a stepped line: a step number holds until it changes. Their history is asked
# for as the last value of each interval, never as its average, which would draw a step that was not
# there: a path object of a tag history binding may carry its own `aggregate`, and `LastValue` is one
# of the modes the binding names (IGW:06-bindings section 7).
STEP_MEMBERS = ["step"]


def history_tags(device_id, member="value", alias="value"):
	"""The `tags` of the trend's tag history binding: a list of path objects, never a path string
	(a string is rejected by the runtime, Cadre-Sandbox-ASM GATEWAY-01 section 5.2). For a device
	without the member the path is empty, as it is before a device is selected. The path object of a
	stepped member (STEP_MEMBERS) carries the aggregate `LastValue`."""
	d = (device_id or "").strip()
	try:
		if d and not system.tag.exists(d + "/" + member):
			d = ""
	except Exception:
		d = ""
	tag = {"path": (d + "/" + member) if d else "", "alias": alias}
	if member in STEP_MEMBERS:
		tag["aggregate"] = "LastValue"
	return [tag]


def trended(session, device_id, members):
	"""Which of `members` a device's trend draws: those the generator's trend index lists for the
	device (`session.custom.trends`: the members the tag model historises, or the device model's
	`trend` list). {member: bool}."""
	out = dict((unicode(m), False) for m in members)
	d = (device_id or "").strip()
	try:
		for t in session.custom.trends:
			if t["deviceId"] == d and t["member"] in out:
				out[unicode(t["member"])] = True
	except Exception:
		pass
	return out


def trend_tags(session, device_id, member):
	"""`history_tags` of one series of a trend that draws several members (the controller's process
	value, setpoint and output), under the member's own name: the path only where the trend index
	lists the member, so the historian is not asked for a member it does not hold."""
	if not trended(session, device_id, [member])[member]:
		return [{"path": "", "alias": member}]
	return history_tags(device_id, member, member)


def tank_tile(device_id):
	"""What the module's tank tile in the faceplate draws: the volume against the capacity where the
	tank's folder carries both (the module's tank has no unit property and labels its value in cubic
	metres, COB-075), else the level against 100; and the trend where the folder carries one.
	Members are looked for before they are read."""
	d = (device_id or "").strip()
	out = {"value": 0.0, "max": 100.0, "trend": "stable"}
	try:
		if d and system.tag.exists(d + "/volume") and system.tag.exists(d + "/capacity"):
			v = system.tag.readBlocking([d + "/volume", d + "/capacity"])
			out.update({"value": float(v[0].value or 0), "max": float(v[1].value or 0)})
		elif d and system.tag.exists(d + "/level"):
			out["value"] = float(system.tag.readBlocking([d + "/level"])[0].value or 0)
		if d and system.tag.exists(d + "/trend"):
			t = unicode(system.tag.readBlocking([d + "/trend"])[0].value or "stable")
			if t in ("fast-rising", "rising", "stable", "falling", "fast-falling"):
				out["trend"] = t
	except Exception:
		pass
	return out


def limit_series(device_id, hours=1):
	"""The trend's limit lines: two points, at the start and the end of the range, carrying each limit
	the device has, so each limit is drawn level across the chart."""
	rows = limit_rows(device_id)
	if not rows:
		return []
	values = system.tag.readBlocking([r["deviceId"] + "/" + r["member"] for r in rows])
	end = system.date.now()
	start = system.date.addHours(end, -int(hours or 1))
	points = []
	for t in (start, end):
		p = {"time": system.date.toMillis(t)}
		for r, qv in zip(rows, values):
			if qv.value is not None:
				p[r["member"]] = float(qv.value)
		points.append(p)
	return points


# Page parts (COB-159, wiki page 05 "Page parts"). A command button of a diagram page pulses a tag the
# descriptors declared (`session.custom.commands`, written by the generator from the descriptors, each entry
# {path, ms}): a script never writes a tag the descriptors did not name. The pulse is write path W18 (the
# admin role, COBD-024), like a device's pulse command.


def _page_command(session, path):
	"""The generator's entry for a declared command tag (`session.custom.commands`: {path, ms}), else None."""
	p = unicode(path or "")
	try:
		for c in session.custom.commands:
			if unicode(c["path"]) == p:
				return c
	except Exception:
		pass
	return None


def page_pulse(session, path):
	"""A page command button's pulse (write path W18, the admin role, COBD-024): true is written to the tag
	`path`, and false again after the length the descriptor gave. Refused without the role, and for a tag
	that is not a declared command of the project (`_page_command`); the role is asked first, so a session
	without it learns nothing of the project's tags. A write the gateway does not make is answered as a
	refusal. Returns an empty string, or the refusal."""
	if not allowed(session, PULSE_PATH):
		return REFUSED
	entry = _page_command(session, path)
	if entry is None:
		return "Refused: not a command of this project"
	p = unicode(entry["path"])
	try:
		ms = int(entry["ms"])
	except Exception:
		return "Refused: the command has no pulse length"
	if ms < 100 or ms > 600000:
		return "Refused: the pulse length is out of range"
	try:
		if not system.tag.exists(p):
			return "Refused: no such tag"
	except Exception:
		return "Refused: no such tag"
	msg = _written(system.tag.writeBlocking([p], [True]), [p])
	if msg:
		return msg

	def release(tag, wait):
		import time
		time.sleep(wait / 1000.0)
		system.tag.writeBlocking([tag], [False])
	system.util.invokeAsynchronous(release, args=[p, ms])
	return ""


def tag_source(tag_path):
	"""The source pattern of the alarms configured on one tag: '[default]site/F1' gives
	'prov:default:/tag:site/F1:/alm:*' (the source form measured by experiment E4, GF-34). A path without
	a provider matches nothing, never everything."""
	d = unicode(tag_path or "").strip()
	if not d.startswith("[") or "]" not in d:
		return NO_MATCH
	prov, path = d[1:].split("]", 1)
	path = path.strip("/")
	if not prov or not path:
		return NO_MATCH
	return "prov:%s:/tag:%s:/alm:*" % (prov, path)


RANGE_BAR_TRACK = "var(--border-divider-color)"
RANGE_BAR_BAND = "var(--element-inactive-color)"
RANGE_BAR_MARK = "var(--element-neutral-color)"
RANGE_BAR_VALUE = "var(--element-active-color)"
RANGE_BAR_BEYOND = "var(--alert-warning-color)"


def _number_or_none(text):
	try:
		return float(text)
	except Exception:
		return None


def range_bar_elements(spec):
	"""The elements of a range bar (`Parts/RangeBar`). `spec` is 'value|min|max|normalLo|normalHi|loLimit|
	hiLimit|vertical', a field empty where the number is absent. The bar is drawn in a 100 by 10 box (10 by
	100 when vertical, the high end at the top): the track, the normal band, a mark at each limit and the
	value marker, which takes the warning colour beyond a limit. Every figure is written here as a plain
	number, so that no number format (and no locale) is involved; a bar with no span draws the track only."""
	f = (unicode(spec or "") + "|" * 8).split("|")
	value, low, high = _number_or_none(f[0]), _number_or_none(f[1]), _number_or_none(f[2])
	nlo, nhi, llo, lhi = _number_or_none(f[3]), _number_or_none(f[4]), _number_or_none(f[5]), _number_or_none(f[6])
	vertical = f[7] == "true"
	out = []

	def box(a, b, c, d, paint, name):
		a, b = max(0.0, min(100.0, a)), max(0.0, min(100.0, b))
		if vertical:
			x0, x1, y0, y1 = c, d, 100.0 - b, 100.0 - a
		else:
			x0, x1, y0, y1 = a, b, c, d
		out.append({"type": "path", "name": name, "fill": {"paint": paint},
			"d": "M%.2f %.2fH%.2fV%.2fH%.2fZ" % (x0, y0, x1, y1, x0)})
	box(0.0, 100.0, 3.0, 7.0, RANGE_BAR_TRACK, "track")
	if low is None or high is None or high <= low:
		return out

	def at(v):
		return 100.0 * (v - low) / (high - low)
	if nlo is not None and nhi is not None and nhi > nlo:
		box(at(nlo), at(nhi), 2.0, 8.0, RANGE_BAR_BAND, "normal")
	for name, v in (("lowLimit", llo), ("highLimit", lhi)):
		if v is not None:
			box(at(v) - 0.6, at(v) + 0.6, 0.0, 10.0, RANGE_BAR_MARK, name)
	if value is not None:
		beyond = (llo is not None and value < llo) or (lhi is not None and value > lhi)
		p = max(1.0, min(99.0, at(value)))
		box(p - 1.0, p + 1.0, 0.0, 10.0, RANGE_BAR_BEYOND if beyond else RANGE_BAR_VALUE, "value")
	return out


# ---------------------------------------------------------------------------------------------------
# The ASM frame (COB-160; DESIGN sections 3 to 6 of the eng02 ASM reimagining). Every function reads the
# frame's state from `session.custom` and answers plain lists and dicts for the views' bindings.
# ---------------------------------------------------------------------------------------------------
NODE_ROUTES = {"/node/alarms": "alarms", "/node/trend": "trend"}
FLOAT_SLOTS = 6
FLOAT_TOP = 90
FLOAT_RIGHT = 5
FLOAT_STEP = 24
SEARCH_GROUP_ROWS = 9
BANNER_ROWS = 3
ROW_DEFAULT = {"kind": "", "label": "", "second": "", "icon": "", "depth": 0, "selected": False, "disabled": False,
	"action": "", "route": "", "nodeId": "", "deviceId": "", "deviceKind": "", "deviceTitle": "",
	"deviceLabel": "", "deviceLocal": "", "tab": "", "close": ""}


def _custom(session, name, default=None):
	"""A value of `session.custom`, else `default`."""
	try:
		v = getattr(session.custom, name)
		if v is None:
			return default
		return v
	except Exception:
		return default


def _text(value):
	return unicode(value if value is not None else "")


def _row(**kw):
	"""One row of the frame's lists (`Framework/ASM/ListRow`): the defaults, then the given fields."""
	r = dict(ROW_DEFAULT)
	r.update(kw)
	if "counts" not in r:
		r["counts"] = _no_counts()
	return r


def _clock(ms):
	try:
		return system.date.format(system.date.fromMillis(long(ms)), "HH:mm:ss")
	except Exception:
		return ""


# --- several floating faceplates (COB-160, DESIGN section 6) ---------------------------------------------
def asm_frame(session):
	"""True while the session runs the ASM frame (`session.custom.frame`, written by `screen.py --frame asm`, or its module
	component variant `--frame obasm`);
	a project built without the option, or before it, answers False and keeps the single floating faceplate."""
	return _text(_custom(session, "frame", "openbridge")) in ("asm", "obasm")


def float_id(device):
	"""The popup id of a device's floating faceplate: one popup per device, so that opening a device that is
	already floating addresses its own popup."""
	out = ""
	for ch in _text(device):
		if ch.isalnum():
			out += ch
		else:
			out += "_"
	return "fp_" + out


def float_slot(session, device):
	"""The place of a device's floating faceplate: a device keeps its slot, a new one takes the next of
	FLOAT_SLOTS, each FLOAT_STEP px from the one before."""
	taken = {}
	try:
		taken = dict(_custom(session, "floating", {}) or {})
	except Exception:
		taken = {}
	key = float_id(device)
	if key not in taken:
		if len(taken) >= 4 * FLOAT_SLOTS:
			taken = {}
		taken[key] = len(taken) % FLOAT_SLOTS
		try:
			session.custom.floating = taken
		except Exception:
			pass
	return int(taken[key])


def float_position(session, device):
	"""The popup position of a device's faceplate: the first 5 px from the right, each further one offset 24 px
	down and to the left."""
	n = float_slot(session, device)
	return {"top": FLOAT_TOP + FLOAT_STEP * n, "right": FLOAT_RIGHT + FLOAT_STEP * n}


def float_params(session, popup_id):
	"""The view parameters of a floating faceplate: the device `select_device` has just selected, with its
	style, the tab `open_device` named and, for a local assembly's device, its kind. The popup reads these, never `session.custom.selected*`, so that
	a second device does not redraw the first."""
	return {"popupId": _text(popup_id), "deviceId": _text(_custom(session, "selectedDevice", "")),
		"kind": _text(_custom(session, "selectedKind", "")), "style": _text(_custom(session, "selectedStyle", "openbridge")),
		"title": _text(_custom(session, "selectedTitle", "")), "label": _text(_custom(session, "selectedLabel", "")),
		"tab": _text(_custom(session, "selectedTab", "")), "localKind": _text(_custom(session, "selectedLocal", ""))}


# --- the node of the current page ------------------------------------------------------------------------
def _node_by_id(session, node_id):
	for n in _hierarchy(session):
		if _text(n["id"]) == _text(node_id):
			return n
	return None


def _first_route(node):
	pages = list(node["pages"] or []) if node is not None else []
	return _text(pages[0]["route"]) if pages else ""


def frame_node(session, route):
	"""The node a page shows: the node whose pages include `route`, else, for the Alarms and Trend pivot
	pages, the node `session.custom.contentNode` names (the root while it is empty). None for a page
	that names no node."""
	nodes = _hierarchy(session)
	if route in NODE_ROUTES:
		wanted = _text(_custom(session, "contentNode", ""))
		found = _node_by_id(session, wanted)
		if found is None and len(nodes) > 0:
			found = nodes[0]
		return found
	here = None
	for n in nodes:
		if len([p for p in (n["pages"] or []) if p["route"] == route]) > 0:
			here = n
	return here


def _chain(session, node):
	by_id = dict((_text(n["id"]), n) for n in _hierarchy(session))
	chain = []
	seen = 0
	while node is not None and seen < 64:
		chain.insert(0, node)
		node = by_id.get(_text(node["parentId"] or ""))
		seen += 1
	return chain


def frame_crumbs(session, route):
	"""The breadcrumb of the ASM frame: the nodes from the root to the current page's node, each with its
	id (the crumb's popup names it), name, the route of its first page, its counts and whether it is the
	first and the last. Empty for a page that names no node."""
	chain = _chain(session, frame_node(session, route))
	if not chain:
		return []
	counts = node_counts(session)
	out = []
	for i, n in enumerate(chain):
		out.append({"nodeId": _text(n["id"]), "name": _text(n["name"]), "route": _first_route(n),
			"counts": counts.get(_text(n["id"]), _no_counts()), "first": i == 0, "last": i == len(chain) - 1})
	return out


def crumb_menu(session, node_id):
	"""The rows of a crumb's popup (DESIGN section 4): Show (Mimic, Alarms, Trend of the node) and Areas
	(its child nodes, each with its badges)."""
	node = _node_by_id(session, node_id)
	if node is None:
		return []
	counts = node_counts(session)
	first = _first_route(node)
	nid = _text(node["id"])
	rows = [_row(kind="group", label="Show"),
		_row(kind="show", label="Mimic", icon="home", action="route" if first else "", route=first,
			nodeId=nid, disabled=not first, close="crumbPopup"),
		_row(kind="show", label="Alarms", icon="alert-list", action="alarms", nodeId=nid, close="crumbPopup"),
		_row(kind="show", label="Trend", icon="trend", action="trend", nodeId=nid, close="crumbPopup")]
	kids = [n for n in _hierarchy(session) if _text(n["parentId"] or "") == nid]
	if kids:
		rows.append(_row(kind="group", label="Areas"))
	for n in kids:
		route = _first_route(n)
		rows.append(_row(kind="area", label=_text(n["name"]), action="route" if route else "alarms", route=route,
			nodeId=_text(n["id"]), counts=counts.get(_text(n["id"]), _no_counts()), close="crumbPopup"))
	return rows


# --- the navigation dock (DESIGN section 3) -------------------------------------------------------------
def _children(session, parent_id):
	return [n for n in _hierarchy(session) if _text(n["parentId"] or "") == _text(parent_id)]


def _node_path(n):
	return _text(n["path"]) if n is not None else ""


def nav_tree(session, query, route):
	"""The rows of the navigation dock: the tree of the hierarchy's nodes, each with its badges and its
	pages beneath it, the current page selected; with a query, a flat list of the nodes and pages that match
	it. A project with no hierarchy lists its navigation items."""
	q = _text(query).strip().lower()
	nodes = _hierarchy(session)
	counts = node_counts(session)
	rows = []
	if not nodes:
		try:
			items = list(session.custom.nav["items"])
		except Exception:
			items = []
		for it in items:
			if q and q not in _text(it["label"]).lower():
				continue
			rows.append(_row(kind="page", label=_text(it["label"]), icon=_text(it["icon"]), route=_text(it["path"]),
				action="route", selected=it["path"] == route, close="nav"))
		return rows

	def node_row(n, depth, flat):
		r = _first_route(n)
		return _row(kind="node", label=_text(n["name"]), second=_node_path(n) if flat else "", depth=depth,
			counts=counts.get(_text(n["id"]), _no_counts()), nodeId=_text(n["id"]), route=r,
			action="route" if r else "alarms", close="nav")

	def page_row(n, p, depth, flat):
		return _row(kind="page", label=_text(p["label"]), second=_node_path(n) if flat else "", depth=depth,
			route=_text(p["route"]), action="route", selected=p["route"] == route, nodeId=_text(n["id"]), close="nav")

	if q:
		for n in nodes:
			if q in _text(n["name"]).lower() or q in _text(n["path"]).lower():
				rows.append(node_row(n, 0, True))
			for p in (n["pages"] or []):
				if q in _text(p["label"]).lower() or q in _text(p["route"]).lower():
					rows.append(page_row(n, p, 0, True))
		return rows

	def walk(n, depth):
		rows.append(node_row(n, depth, False))
		for p in (n["pages"] or []):
			rows.append(page_row(n, p, depth + 1, False))
		for k in _children(session, n["id"]):
			walk(k, depth + 1)
	for n in nodes:
		if not _text(n["parentId"] or ""):
			walk(n, 0)
	return rows


def nav_footer(session, route):
	"""The footer of the navigation dock: the support pages, those navigation items that name no node (the
	trend page and the like) and the frame's footer items (the alerts page)."""
	rows = []
	try:
		items = list(session.custom.nav["items"])
	except Exception:
		items = []
	try:
		footer = list(session.custom.nav["footer"])
	except Exception:
		footer = []
	for it in items:
		node = ""
		try:
			node = _text(it["node"])
		except Exception:
			pass
		if node == "" and len(_hierarchy(session)) > 0:
			rows.append(_row(kind="page", label=_text(it["label"]), icon=_text(it["icon"]), route=_text(it["path"]),
				action="route", selected=it["path"] == route, close="nav"))
	for it in footer:
		rows.append(_row(kind="page", label=_text(it["label"]), icon=_text(it["icon"]), route=_text(it["path"]),
			action="route", selected=it["path"] == route, close="nav"))
	return rows


def nav_support(session, route):
	"""The support list of the navigation dock (L4, `navPanel` "support"): all alarms (the Alarms pivot page of the
	root node), then the footer rows of `nav_footer` (the navigation items that name no node: trends, tools; and
	the alerts page)."""
	rows = [_row(kind="page", label="All alarms", icon="alert-list", action="alarms", nodeId="",
		selected=route == "/node/alarms", close="nav")]
	return rows + nav_footer(session, route)


# --- the page header (DESIGN section 3 item 2) ----------------------------------------------------------
def page_header(session, route):
	"""The page header of a route: the title and its display level, the node the pivot (Mimic, Alarms,
	Trend) acts on, the node's pages as tabs where it has several, and the previous and next pages."""
	out = {"title": page_title(session, route), "level": "", "nodeId": "", "mode": "mimic", "mimicRoute": "",
		"tabs": [], "previous": {"route": "", "title": "", "enabled": False},
		"next": {"route": "", "title": "", "enabled": False}}
	info = {}
	try:
		info = dict(dict(_custom(session, "pageInfo", {}) or {}).get(route) or {})
	except Exception:
		info = {}
	node = frame_node(session, route)
	if route in NODE_ROUTES:
		out["mode"] = NODE_ROUTES[route]
		out["title"] = (_text(node["name"]) if node is not None else "") + (" alarms" if route == "/node/alarms" else " trend")
	elif info:
		out["title"] = _text(info.get("title") or out["title"])
		out["level"] = _text(info.get("level") or "")
		for k in ("previous", "next"):
			target = _text(info.get(k) or "")
			out[k] = {"route": target, "title": _text(info.get(k + "Title") or ""), "enabled": target != ""}
	if node is not None:
		out["nodeId"] = _text(node["id"])
		out["mimicRoute"] = _first_route(node)
		pages = list(node["pages"] or [])
		if len(pages) > 1 and route not in NODE_ROUTES:
			out["tabs"] = [{"label": _text(p["label"]), "route": _text(p["route"]), "selected": p["route"] == route}
				for p in pages]
	return out


def node_devices(session, node_id):
	"""The device folders of a node and of every node beneath it ('' means every node)."""
	nodes = _hierarchy(session)
	want = set()
	if _text(node_id) == "":
		return [_text(d) for n in nodes for d in (n["devices"] or [])]
	todo = [_text(node_id)]
	seen = 0
	while todo and seen < 256:
		cur = todo.pop()
		want.add(cur)
		todo += [_text(n["id"]) for n in nodes if _text(n["parentId"] or "") == cur]
		seen += 1
	return [_text(d) for n in nodes if _text(n["id"]) in want for d in (n["devices"] or [])]


def node_sources(session, node_id):
	"""The alarm source patterns of a node's devices, comma separated, as the stock alarm table takes them
	(GF-52); the no-match pattern while the node has no device with an alarm, never the whole scope."""
	out = []
	for d in node_devices(session, node_id):
		for p in device_sources(session, d):
			if p != NO_MATCH and p not in out:
				out.append(p)
	return ",".join(out) if out else NO_MATCH


def node_trends(session, node_id, hours):
	"""The trend cards of a node: the entries of `session.custom.trends` whose device the node or a node
	beneath it holds, each with the page's range."""
	want = set(node_devices(session, node_id))
	out = []
	for t in (_custom(session, "trends", []) or []):
		if _text(t["deviceId"]) in want:
			r = dict(t)
			r["hours"] = hours
			out.append(r)
	return out


# --- the global search (DESIGN section 5) ----------------------------------------------------------------
def _rank(q, fields):
	"""0 exact on the id (the first field), 1 a prefix or an exact match of another field, 2 a substring,
	9 no match."""
	best = 9
	for i, f in enumerate(fields):
		s = _text(f).lower()
		if not s:
			continue
		if s == q:
			r = 0 if i == 0 else 1
		elif s.startswith(q):
			r = 1
		elif q in s:
			r = 2
		else:
			continue
		if r < best:
			best = r
	return best


def _ranked(q, entries, fields_of):
	scored = []
	for i, e in enumerate(entries):
		r = _rank(q, fields_of(e))
		if r < 9:
			scored.append((r, i))
	scored.sort()
	return [entries[i] for r, i in scored[:SEARCH_GROUP_ROWS]]


def search(session, query):
	"""The rows of the top bar's search popup: Pages, Devices and Tags that match `query`, in that order,
	each group ranked exact id, prefix, substring; at most 30 rows in all, the group titles included."""
	q = _text(query).strip().lower()
	if q == "":
		return []
	index = dict(_custom(session, "searchIndex", {}) or {})
	pages = list(index.get("pages") or [])
	devices = list(index.get("devices") or [])
	tags = list(index.get("tags") or [])
	rows = []
	found = _ranked(q, pages, lambda p: [_text(p[0]).lstrip("/"), p[1], p[2]])
	if found:
		rows.append(_row(kind="group", label="Pages"))
	for p in found:
		rows.append(_row(kind="page", label=_text(p[1]), second=_text(p[2]) + ("  " + _text(p[3]) if p[3] else ""),
			icon="home", action="route", route=_text(p[0]), close="search"))
	found = _ranked(q, devices, lambda d: [_text(d[0]).split("/")[-1], d[2], d[3], d[1]])
	if found:
		rows.append(_row(kind="group", label="Devices"))
	for d in found:
		rows.append(_device_row(d, "home", _text(d[3]) or _text(d[5])))
	found = _ranked(q, tags, lambda t: [_text(t[0]).split("/")[-1], t[0], t[1], t[2]])
	if found:
		rows.append(_row(kind="group", label="Tags"))
	for t in found:
		d = None
		try:
			if int(t[3]) >= 0:
				d = devices[int(t[3])]
		except Exception:
			d = None
		second = _text(t[1]) + ("  " + _text(t[2]) if t[2] else "")
		if d is not None:
			row = _device_row(d, _text(t[4]) or "home", second)
			row["kind"] = "tag"
			row["label"] = _text(t[0]).split("/")[-1]
			row["icon"] = "trend"
			rows.append(row)
		else:
			rows.append(_row(kind="tag", label=_text(t[0]).split("/")[-1], second=second, icon="trend", disabled=True,
				close="search"))
	return rows[:30]


def _device_row(d, tab, second):
	"""A search row for a device: its page, then its faceplate on `tab` where the kind has one."""
	has = len(d) > 6 and int(d[6]) == 1
	return _row(kind="device", label=_text(d[2]) or _text(d[0]).split("/")[-1], second=_text(second), icon="home",
		action="route" if d[4] else "", route=_text(d[4]), deviceId=_text(d[0]) if has else "", deviceKind=_text(d[1]),
		deviceTitle=_text(d[2]), deviceLabel=_text(d[3]), deviceLocal=_text(d[7]) if len(d) > 7 else "", tab=tab,
		close="search")


def search_first(session, query):
	"""The first row of a search that acts, else None: what Enter in the search field does."""
	for r in search(session, query):
		if r["kind"] != "group" and not r["disabled"]:
			return r
	return None


# --- the bottom alarm banner (DESIGN section 3 item 4) ----------------------------------------------------
def banner_alarms(session, route=""):
	"""The three most important alarms (unacknowledged first, then priority, then newest) as rows for
	`Framework/ASM/BannerRow`, with the active alarms counted by priority. With the route of the open page (L5), those
	of the page's node and of every node beneath it: the sources of the node's devices (`node_sources`); on the Alarms and
	Trend pivot pages, those of the node `session.custom.contentNode` names. A page with no node, the pivot
	pages of the root, and a call without a route show the session's whole alarm scope. The counts follow the rows."""
	out = {"rows": [], "counts": _no_counts()}
	try:
		scope = session.custom.alarmScope
	except Exception:
		scope = "*"
	paths = [scope or "*"]
	route = _text(route)
	node = frame_node(session, route) if route else None
	if node is not None and route in NODE_ROUTES and _text(_custom(session, "contentNode", "")) == "":
		node = None
	if node is not None:
		paths = _paths(scope, node_sources(session, _text(node["id"])))
	try:
		events = system.alarm.queryStatus(path=paths, state=LIST_STATES)
	except Exception:
		return out
	devices = _devices_of(session)
	by_folder = dict((_text(d["folder"]), d) for d in devices)
	owner = {}
	for n in _hierarchy(session):
		for d in (n["devices"] or []):
			owner[_text(d)] = _text(n["name"])
	recs = []
	for e in events:
		rec = alert_record(e, devices)
		priority = _text(_accessor(e, "getPriority"))
		active = rec["active"] is True
		unacked = rec["acknowledged"] is False
		if active:
			c = out["counts"]
			if priority in c:
				c[priority] += 1
			c["total"] += 1
			if unacked:
				c["unacked"] += 1
		rank = PRIORITIES.index(priority) if priority in PRIORITIES else len(PRIORITIES) - 1
		recs.append((0 if unacked else 1, rank, -(rec["time"] or 0), rec, priority, active, unacked))
	recs.sort(key=lambda r: (r[0], r[1], r[2]))
	for flag, rank, neg, rec, priority, active, unacked in recs[:BANNER_ROWS]:
		folder = _text(rec["tagId"])
		d = by_folder.get(folder)
		if active and unacked:
			state = "Unacknowledged"
		elif active:
			state = "Acknowledged"
		else:
			state = "Cleared, unacknowledged"
		out["rows"].append({"id": _text(rec["id"]), "priority": priority, "status": PRIORITY_STATUS.get(priority, "") or "neutral",
			"unacked": unacked, "time": _clock(rec["time"]), "node": owner.get(folder, ""),
			"tag": _text(d["title"]) if d is not None else folder.split("/")[-1], "text": _text(rec["text"]),
			"state": state, "deviceId": folder if d is not None else "", "deviceKind": _text(d["kind"]) if d is not None else "",
			"deviceTitle": _text(d["title"]) if d is not None else "", "deviceLabel": _text(d["label"]) if d is not None else "",
			"deviceLocal": _text(_entry_local(d)) if d is not None else ""})
	return out


# --- the module frame (`--frame ob`, tools/hmi/obframe.py) ----------------------------------------------
# The Cadre priority to the count of the package's `AlertCounts` (wiki 13 section 11.1: Critical the critical colour,
# High alarm, Medium warning, Low caution, Diagnostic its own level), for the `alerts` of a navigation item.
OB_COUNT_OF = {"Critical": "countLevelCritical", "High": "countAlarm", "Medium": "countWarning", "Low": "countCaution",
	"Diagnostic": "countLevelDiagnostic"}


def ob_items(kind, rows, state=None, icons=None):
	"""The item objects of the module's frame components (`items` of `cadre.ob.alertmenu` and
	`cadre.ob.navigationmenu`: `tag`, the element's attributes, `id`, `children`), built from rows the library already
	answers. It reads nothing but its arguments (and formats the times).

	`kind` "alerts": `rows` are `alarm_list` records, `state` whether the session may acknowledge (W8). A row is an
	`obc-alert-menu-item` whose `id` is the alarm event's id; ACK shows while the alarm is unacknowledged and is disabled
	without the permission (the scripts refuse anyway, `ack`).
	`kind` "nav": `rows` are navigation items (`nav_items`, or the footer: `label`, `path`, `icon`, optional `counts`),
	`state` the current route, `icons` the package icon names the module bundles. An item's `id` is its route and an
	item that names a node shows the node's counts as `alerts`. An icon outside `icons` is left out."""
	out = []
	if kind == "alerts":
		for r in (rows or []):
			acked = r["acknowledged"] is not False
			day = ""
			try:
				day = system.date.format(system.date.fromMillis(long(r["time"])), "d MMM")
			except Exception:
				pass
			out.append({"tag": "obc-alert-menu-item", "id": _text(r["id"]), "title": _text(r["text"]),
				"description": _text(r["source"]), "day": day, "time": _clock(r["time"]),
				"status": "acknowledged" if acked else "unacknowledged",
				"primaryActionState": "enabled" if state else "disabled",
				"children": [{"tag": "obc-alert-icon", "slot": "alert-icon", "type": r["type"],
					"active": r["active"] is True, "acknowledged": acked}]})
		return out
	for it in (rows or []):
		path = _text(it["path"])
		icon = ""
		counts = None
		try:
			icon = _text(it["icon"])
		except Exception:
			pass
		try:
			counts = it["counts"]
		except Exception:
			pass
		item = {"tag": "obc-navigation-item", "id": path, "label": _text(it["label"]), "checked": path == _text(state)}
		if icon and icon in (icons or []):
			item["hasIcon"] = True
			item["children"] = [{"tag": "obi-" + icon, "slot": "icon"}]
		if counts is not None and counts["total"] > 0:
			item["alerts"] = dict((OB_COUNT_OF[p], counts[p]) for p in OB_COUNT_OF)
		out.append(item)
	return out


# --- the module frame, ASM variant (`--frame obasm`, tools/hmi/obasm.py) ---------------------------------
PIVOT_PAGES = (("mimic", "Mimic"), ("alarms", "Alarms"), ("trend", "Trend"))
ROW_ACTION_KEYS = ("action", "route", "nodeId", "deviceId", "deviceKind", "deviceTitle", "deviceLabel", "tab", "close")


def _alerts_of(counts):
	"""The `alerts` object of a row of the tree or the navigation menu from a node's counts (the same table as `ob_items`), else None."""
	if counts is None or counts["total"] <= 0:
		return None
	return dict((OB_COUNT_OF[p], counts[p]) for p in OB_COUNT_OF)


def _tree_rows(rows, route):
	"""The tree rows of `nav_tree`'s list: a node row is followed by the rows beneath it, deeper by one. A row that is followed by
	deeper rows is a group (open while the page of `route` stands in it), any other a leaf; a node group with no page of its own
	gets an Alarms leaf, so that its destination (the Alarms page of the node) stays reachable. Each row gets an `id`."""
	roots = []
	stack = []
	for i in range(len(rows)):
		r = rows[i]
		rid = "n:" + _text(r["nodeId"]) if r["kind"] == "node" else "p:" + _text(r["route"]) if _text(r["route"]) else "r" + unicode(i)
		item = {"row": r, "id": rid, "children": [], "checked": r["selected"] is True}
		depth = int(r["depth"] or 0)
		while stack and stack[-1][0] >= depth:
			stack.pop()
		if stack:
			stack[-1][1]["children"].append(item)
		else:
			roots.append(item)
		stack.append((depth, item))
	return roots


def _tree_item(node):
	"""The tree object of `_tree_rows`' node, and whether it holds the checked row."""
	r = node["row"]
	open_ = node["checked"]
	kids = []
	for k in node["children"]:
		o, inside = _tree_item(k)
		kids.append(o)
		open_ = open_ or inside
	out = {"id": node["id"], "label": _text(r["label"])}
	alerts = _alerts_of(r["counts"]) if r["kind"] == "node" else None
	if alerts is not None:
		out["alerts"] = alerts
	if kids:
		out["tag"] = "obc-tree-navigation-group"
		out["hasIcon"] = False
		out["expanded"] = open_
		if r["kind"] == "node" and not _text(r["route"]):
			kids.insert(0, {"tag": "obc-tree-navigation-item", "id": node["id"] + ":alarms", "label": "Alarms", "hasLeadingIcon": False})
		out["children"] = kids
	else:
		out["tag"] = "obc-tree-navigation-item"
		out["hasLeadingIcon"] = False
		out["checked"] = node["checked"]
	return out, open_


def _stored(r, rid):
	"""The part of a row a press needs, with its `id` (kept in the view for the event script)."""
	out = dict((k, _text(r[k])) for k in ROW_ACTION_KEYS)
	out["id"] = rid
	return out


def obasm_items(kind, data, state=None, icons=None):
	"""The items of the ASM variant's components, built from lists the library already answers; it reads nothing but its
	arguments.

	`kind` "pivot": `data` is the node's first page route (the head's `mimicRoute`); the three `obc-pivot-item` of the header, Mimic
	disabled while the node has no page. `kind` "tabs": `data` is the head's `tabs`; the `tabs` of the tab row (`id` the page's route).
	`kind` "tab": the same `data`; the id of the selected tab.
	`kind` "tree": `data` is `nav_tree`'s rows, `state` the current route, `icons` as for `ob_items`; answers {"rows", "items"}: the rows
	a press looks up by `id`, and the tree (`obc-tree-navigation-group` and `-item`, `alerts` from the node's counts).
	`kind` "support": `data` is `nav_support`'s rows; answers {"rows", "items"} with `obc-navigation-item` (an icon outside `icons` is left out)."""
	if kind == "pivot":
		return [{"tag": "obc-pivot-item", "id": k, "value": k, "label": label, "hasLabel": True,
			"disabled": k == "mimic" and _text(data) == ""} for k, label in PIVOT_PAGES]
	if kind == "tabs":
		return [{"id": _text(t["route"]), "title": _text(t["label"])} for t in (data or [])]
	if kind == "tab":
		for t in (data or []):
			if t["selected"] is True:
				return _text(t["route"])
		return ""
	rows = list(data or [])
	if kind == "tree":
		items = []
		stored = []
		nodes = _tree_rows(rows, state)
		todo = list(nodes)
		while todo:
			n = todo.pop(0)
			stored.append(_stored(n["row"], n["id"]))
			if n["children"] and n["row"]["kind"] == "node" and not _text(n["row"]["route"]):
				a = _stored(n["row"], n["id"] + ":alarms")
				a["route"] = ""
				a["action"] = "alarms"
				stored.append(a)
			todo = n["children"] + todo
		for n in nodes:
			items.append(_tree_item(n)[0])
		return {"rows": stored, "items": items}
	out = []
	stored = []
	for i in range(len(rows)):
		r = rows[i]
		rid = "s:" + (_text(r["route"]) or _text(r["action"]) or unicode(i))
		stored.append(_stored(r, rid))
		item = {"tag": "obc-navigation-item", "id": rid, "label": _text(r["label"]), "checked": r["selected"] is True}
		icon = _text(r["icon"])
		if icon and icon in (icons or []):
			item["hasIcon"] = True
			item["children"] = [{"tag": "obi-" + icon, "slot": "icon"}]
		out.append(item)
	return {"rows": stored, "items": out}
